export function musicMetadata(musicId: number): MusicMetadata | null {
  const normalized = Number(musicId);
  if (!Number.isFinite(normalized) || normalized < 0) return null;
  return MUSIC_METADATA[String(Math.floor(normalized))] || null;
}

export function chartDifficulty(
  musicId: number,
  gameCode: string,
  playMode: 'standard' | 'classic',
  seqMode: number
): number {
  const metadata = musicMetadata(musicId);
  const seq = Math.floor(Number(seqMode));
  if (!metadata || !Number.isFinite(seq)) return 0;
  const drum = String(gameCode || '').toUpperCase() === 'K32';
  if (playMode === 'classic') {
    const index = drum
      ? (seq >= 1 && seq <= 3 ? seq + 12 : -1)
      : (seq >= 1 && seq <= 3
        ? seq
        : seq >= 4 && seq <= 6
          ? seq + 1
          : seq >= 7 && seq <= 9 ? seq + 2 : -1);
    return index >= 0 ? Number(metadata.classicDifficulties[index]) || 0 : 0;
  }
  const index = drum
    ? (seq >= 1 && seq <= 4 ? seq + 5 : -1)
    : (seq >= 1 && seq <= 4
      ? seq
      : seq >= 5 && seq <= 8 ? seq + 6 : -1);
  return index >= 0 ? Number(metadata.standardDifficulties[index]) || 0 : 0;
}

export function isClassicNewMusic(musicId: number, gameCode: string): boolean {
  const metadata = musicMetadata(musicId);
  if (!metadata) return false;
  return String(gameCode || '').toUpperCase() === 'K32'
    ? metadata.firstClassicVersionK32 === 17
    : metadata.firstClassicVersionK33 === 18;
}

